import math, itertools
# Basic presence checks
if 'dimension' not in assign or 'side_lengths' not in assign or 'sides' not in assign:
    # missing data
    return (False, None)
d = assign['dimension']
side_lengths_str = assign['side_lengths']
sides = assign['sides']
# Type and domain checks
if not isinstance(d, int):
    return (False, None)
if d < 4:
    # enforce higher dimension than seed
    return (False, None)
if not isinstance(sides, (list, tuple)):
    return (False, None)
if len(sides) != d:
    return (False, None)
try:
    sides_int = [int(x) for x in sides]
except Exception:
    return (False, None)
if any(x < 2 for x in sides_int):
    return (False, None)
# Ensure the presented string matches the numeric sides to prevent tampering
normalized_str = ', '.join(str(x) for x in sides_int)
if normalized_str != side_lengths_str:
    # mismatch between string and numeric sides
    return (False, None)
# Difficulty enforcement: require nontrivial gcd structure
def gcd_list(lst):
    g = 0
    for x in lst:
        g = math.gcd(g, x)
    return g
pair_gcds = []
for i in range(d):
    for j in range(i+1, d):
        pair_gcds.append(math.gcd(sides_int[i], sides_int[j]))
triple_gcds = []
for i in range(d):
    for j in range(i+1, d):
        for k in range(j+1, d):
            triple_gcds.append(gcd_list([sides_int[i], sides_int[j], sides_int[k]]))
positives_pair = [g for g in pair_gcds if g > 1]
positives_triple = [g for g in triple_gcds if g > 1]
distinct_pair = set(positives_pair)
if len(distinct_pair) < 2:
    # not enough distinct pairwise gcd structure
    return (False, None)
if len(positives_triple) < 1:
    # need at least one triple gcd > 1 to force higher-order inclusion-exclusion
    return (False, None)
if gcd_list(sides_int) != 1:
    # avoid the trivial case where all sides share a common factor
    return (False, None)
# Compute the number of unit hypercubes intersected by the interior of the space diagonal
# Inclusion-exclusion: sum over nonempty subsets S of indices of gcd of (a_i for i in S), with sign (-1)^(|S|-1)
total = 0
indices = range(d)
for k in range(1, d+1):
    s_k = 0
    for idxs in itertools.combinations(indices, k):
        g = 0
        for idx in idxs:
            g = math.gcd(g, sides_int[idx])
        s_k += g
    if (k - 1) % 2 == 0:
        total += s_k
    else:
        total -= s_k
answer = total
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

